import{_ as i,o as e,c as a,ag as t}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 법가 사상의 핵심 전제와 목적","slug":"_1-법가-사상의-핵심-전제와-목적","link":"#_1-법가-사상의-핵심-전제와-목적","children":[{"level":3,"title":"인간관 및 사회시스템의 필요성","slug":"인간관-및-사회시스템의-필요성","link":"#인간관-및-사회시스템의-필요성","children":[]},{"level":3,"title":"한비자의 종합","slug":"한비자의-종합","link":"#한비자의-종합","children":[]}]},{"level":2,"title":"2. 상앙의 사상","slug":"_2-상앙의-사상","link":"#_2-상앙의-사상","children":[{"level":3,"title":"부국강병과 인간 본성의 활용","slug":"부국강병과-인간-본성의-활용","link":"#부국강병과-인간-본성의-활용","children":[]},{"level":3,"title":"군주의 역할","slug":"군주의-역할","link":"#군주의-역할","children":[]},{"level":3,"title":"상앙의 핵심 통치 방책","slug":"상앙의-핵심-통치-방책","link":"#상앙의-핵심-통치-방책","children":[{"level":4,"title":"1) 법 (法)","slug":"_1-법-法","link":"#_1-법-法","children":[]},{"level":4,"title":"2) 농업과 군역 강조","slug":"_2-농업과-군역-강조","link":"#_2-농업과-군역-강조","children":[]},{"level":4,"title":"3) 상벌의 엄격한 진행과 덕치 비판","slug":"_3-상벌의-엄격한-진행과-덕치-비판","link":"#_3-상벌의-엄격한-진행과-덕치-비판","children":[]}]}]},{"level":2,"title":"3. 법가의 능력주의적 요소와 한계","slug":"_3-법가의-능력주의적-요소와-한계","link":"#_3-법가의-능력주의적-요소와-한계","children":[]},{"level":2,"title":"4. 한비자의 사상","slug":"_4-한비자의-사상","link":"#_4-한비자의-사상","children":[{"level":3,"title":"인간 본성과 통치 원칙","slug":"인간-본성과-통치-원칙","link":"#인간-본성과-통치-원칙","children":[]},{"level":3,"title":"덕치 정치 비판","slug":"덕치-정치-비판","link":"#덕치-정치-비판","children":[]},{"level":3,"title":"세론 (勢論)","slug":"세론-勢論","link":"#세론-勢論","children":[]},{"level":3,"title":"갈등의 해결","slug":"갈등의-해결","link":"#갈등의-해결","children":[]}]}],"relativePath":"philosophy/China/05. 법가.md","filePath":"philosophy/China/05. 법가.md"}'),r={name:"philosophy/China/05. 법가.md"};function n(o,l,s,h,p,u){return e(),a("div",null,[...l[0]||(l[0]=[t('<h2 id="_1-법가-사상의-핵심-전제와-목적" tabindex="-1">1. 법가 사상의 핵심 전제와 목적 <a class="header-anchor" href="#_1-법가-사상의-핵심-전제와-목적" aria-label="Permalink to &quot;1. 법가 사상의 핵심 전제와 목적&quot;">​</a></h2><h3 id="인간관-및-사회시스템의-필요성" tabindex="-1">인간관 및 사회시스템의 필요성 <a class="header-anchor" href="#인간관-및-사회시스템의-필요성" aria-label="Permalink to &quot;인간관 및 사회시스템의 필요성&quot;">​</a></h3><ul><li><p><strong>인간 불신:</strong> 인간을 신뢰하지 않았기 때문에 법과 제도, 사회시스템을 강조함.</p></li><li><p><strong>인간의 본성:</strong> 이기적인 성향을 인간의 본성으로 보고, 이익을 좋아하고 손해를 싫어하는 이기심의 적절한 추구를 긍정함.</p></li><li><p><strong>이기심의 유도와 조정:</strong> 이기심이 적절하게 실현되도록 유도하는 것을 매우 중요하게 여김. 개인의 이기심 실현이 타자의 이기심 실현과 충돌하지 않으면 됨.</p></li><li><p><strong>시스템의 강력한 적용:</strong> 개인의 이기심 실현이 공동체 전체의 이기심 실현으로 연결될 수 있는 시스템을 마련한 후, 이를 강력하게 적용하는 것이 필요함.</p></li><li><p><strong>통치 방식:</strong> 덕이 있는 현자는 필요하지 않으며, 법과 제도를 갖추고 이를 적절히 운영하기만 하면 됨.</p></li></ul><h3 id="한비자의-종합" tabindex="-1">한비자의 종합 <a class="header-anchor" href="#한비자의-종합" aria-label="Permalink to &quot;한비자의 종합&quot;">​</a></h3><ul><li>한비자는 상앙의 <strong>법(法)</strong>, 신불해의 <strong>술(術)</strong>, 신도의 세(勢)를 종합함.</li></ul><h2 id="_2-상앙의-사상" tabindex="-1">2. 상앙의 사상 <a class="header-anchor" href="#_2-상앙의-사상" aria-label="Permalink to &quot;2. 상앙의 사상&quot;">​</a></h2><h3 id="부국강병과-인간-본성의-활용" tabindex="-1">부국강병과 인간 본성의 활용 <a class="header-anchor" href="#부국강병과-인간-본성의-활용" aria-label="Permalink to &quot;부국강병과 인간 본성의 활용&quot;">​</a></h3><ul><li><p><strong>최종 목표:</strong> 인격 성숙을 통한 안정화가 아니라, 부국강병에 있음.</p></li><li><p><strong>인간 행동 패턴 파악:</strong> 인간의 본성은 이익을 좋아하고 해로움을 싫어하는 존재임. 또한 무엇이 이롭고 해로운지를 합리적으로 사고하고 비교해본 후 더 이로운 것을 선택함.</p></li><li><p><strong>통치 방향:</strong> 인간은 원래 그런 존재이므로 바꾸려고 하기보다, 적절히 이용해서 국가가 원하는 방향으로 유도하면 됨.</p></li></ul><h3 id="군주의-역할" tabindex="-1">군주의 역할 <a class="header-anchor" href="#군주의-역할" aria-label="Permalink to &quot;군주의 역할&quot;">​</a></h3><ul><li><p>군주는 국가의 이익을 실현하고 국가 질서를 바로잡아 주는 존재임.</p></li><li><p>인간은 무리생활을 해야만 하므로 질서가 없다면 다툼이 발생할 수밖에 없고, 이 다툼이 해소되지 않으면 공존이 불가능하기 때문에 질서를 바로잡아 줄 존재가 필요함.</p></li></ul><h3 id="상앙의-핵심-통치-방책" tabindex="-1">상앙의 핵심 통치 방책 <a class="header-anchor" href="#상앙의-핵심-통치-방책" aria-label="Permalink to &quot;상앙의 핵심 통치 방책&quot;">​</a></h3><h4 id="_1-법-法" tabindex="-1">1) 법 (法) <a class="header-anchor" href="#_1-법-法" aria-label="Permalink to &quot;1) 법 (法)&quot;">​</a></h4><ul><li><p><strong>통치의 객관적 기준:</strong> 백성이 많아지면 사악한 일이 많이 일어나므로, 법과 제도를 세워 그것을 기준 삼아 금지해야 함.</p></li><li><p><strong>투명한 공개:</strong> 법은 투명하게 공개되어야 함. 관리가 백성이 법을 안다는 사실을 알아야 관리가 법이 아닌 것으로 백성을 대하지 못하고, 백성은 법을 넘어 법관을 침해하지 못함.</p></li><li><p><strong>획일적 적용:</strong> 법은 백성 위에서 획일적으로 적용되어야 함. 잘못과 범죄가 사적 관계로 인해 덮어지면 사사로운 힘이 법질서를 눌러버림. 죄가 반드시 처벌되어야 법이 사람 위에 서게 되고 국가가 강해짐.</p></li></ul><h4 id="_2-농업과-군역-강조" tabindex="-1">2) 농업과 군역 강조 <a class="header-anchor" href="#_2-농업과-군역-강조" aria-label="Permalink to &quot;2) 농업과 군역 강조&quot;">​</a></h4><ul><li><p><strong>기본 방향:</strong> 농업은 부의 원천이므로 농업 부흥책이 필요하며, 농업에 방해가 되는 것들은 철저히 제거함. 병력 확보는 강병의 원천임.</p></li><li><p><strong>동기 부여:</strong> 농업은 힘들고 전쟁은 무섭지만 백성이 하는 이유는 이익(살아서는 이익, 죽어서는 명예)을 위해서임. 농업에서 이익이 나오고 전쟁에서 명예가 나오면 열심히 할 것임.</p></li><li><p><strong>타 분야 억제:</strong> 쉽게 돈을 벌 수 있는 상공업을 억제하고 쉽게 명예를 얻을 수 있는 유학 등을 배제하여, 농업과 전쟁 외의 분야에서는 이익과 명예를 얻을 수 없게 함.</p></li><li><p><strong>신분 및 자원 관리:</strong> 귀족의 세습적 특권을 약화시키고 군공에 따라 신분을 부여하려 함. 효율적 자원 관리를 위해 백성의 수·정보·가진 자원을 기록하여 관리함.</p></li><li><p><strong>철저한 형벌과 포상:</strong> 우수한 병력의 손실을 막기 위해 병역 기피에 대한 처벌을 전장에서 느끼는 죽음의 공포보다 더 가혹하게 함. 반면, 전장에서 무공에 대한 포상은 매우 후하게 함.</p></li></ul><h4 id="_3-상벌의-엄격한-진행과-덕치-비판" tabindex="-1">3) 상벌의 엄격한 진행과 덕치 비판 <a class="header-anchor" href="#_3-상벌의-엄격한-진행과-덕치-비판" aria-label="Permalink to &quot;3) 상벌의 엄격한 진행과 덕치 비판&quot;">​</a></h4><ul><li><p><strong>상벌의 동기부여:</strong> 인간의 본성은 이익을 좋아하고 손해를 싫어하므로, 형벌과 보상은 인간의 에너지를 부국강병이라는 목표로 움직이게 만드는 동기를 부여함. 따라서 신상필벌에 따라 백성을 다스려야 함.</p></li><li><p><strong>덕치 거부:</strong> 덕이 아닌 법으로 다스려야 함. 어진 사람은 남에게 어질게 대할 수는 있어도 남을 어질게 만들 수는 없음. 성인은 인(仁)과 의(義)로는 세상을 다스리기 적합하지 않다는 이치를 앎.</p></li></ul><h2 id="_3-법가의-능력주의적-요소와-한계" tabindex="-1">3. 법가의 능력주의적 요소와 한계 <a class="header-anchor" href="#_3-법가의-능력주의적-요소와-한계" aria-label="Permalink to &quot;3. 법가의 능력주의적 요소와 한계&quot;">​</a></h2><ul><li><p><strong>법의 선택 이유:</strong> 인간은 사적 욕망으로 가득 찬 존재이며, 착한 사람은 우연적으로 존재하기 때문임.</p></li><li><p><strong>능력주의적 요소:</strong> 기준은 오로지 능력임. 법가는 귀족적 세습 질서를 부정하고 공적 기능에 따라 사람을 평가한다는 점에서 능력주의적 요소를 지님.</p></li><li><p><strong>현대와의 차이점:</strong> 평등한 기회 보장과 자유로운 개인의 발전을 지향하는 현대의 능력주의와는 차이가 있음. 전쟁과 농업에 유용한 능력만을 중시하고 군주가 원하는 결과를 지향하기 때문임.</p></li></ul><h2 id="_4-한비자의-사상" tabindex="-1">4. 한비자의 사상 <a class="header-anchor" href="#_4-한비자의-사상" aria-label="Permalink to &quot;4. 한비자의 사상&quot;">​</a></h2><h3 id="인간-본성과-통치-원칙" tabindex="-1">인간 본성과 통치 원칙 <a class="header-anchor" href="#인간-본성과-통치-원칙" aria-label="Permalink to &quot;인간 본성과 통치 원칙&quot;">​</a></h3><ul><li><p><strong>이기적 본성:</strong> 인간은 이기적인 존재이며 이익이 있는 곳에서는 용감해짐. 이익을 좋아하고 손해를 싫어하는 것이 사람의 본성임.</p></li><li><p><strong>도덕성의 외재성:</strong> 연민, 배려, 공감은 인간의 본성에서 나오는 것이 아니며 외적 조건에 따라 나올 수도 있고 나오지 않을 수도 있음. 인간의 선행은 내재된 도덕성의 발현이 아니라 상황과 조건에 따른 법에 의한 통치로 가능함.</p></li><li><p><strong>법치주의:</strong> 사람은 믿을 만한 존재가 아니기 때문에 양심에 따른 정치가 아닌 법에 의한 정치(인치·덕치가 아닌 법치)를 해야 함.</p></li></ul><h3 id="덕치-정치-비판" tabindex="-1">덕치 정치 비판 <a class="header-anchor" href="#덕치-정치-비판" aria-label="Permalink to &quot;덕치 정치 비판&quot;">​</a></h3><ul><li><strong>신상필벌로의 전환:</strong> 군주가 아랫사람의 행위는 규제하지 못하면서 자신의 행위만을 다스리는 솔선수범의 태도를 비판함. 나라에 이로움을 더한 사람에게는 반드시 상을 주고, 명을 더럽힌 사람에게는 반드시 벌을 주어야 함.</li></ul><h3 id="세론-勢論" tabindex="-1">세론 (勢論) <a class="header-anchor" href="#세론-勢論" aria-label="Permalink to &quot;세론 (勢論)&quot;">​</a></h3><ul><li><p><strong>권력의 필요성:</strong> 규칙과 제도를 공정하고 엄격하게 운영하기 위해서는 반드시 힘이 필요하므로, 군주에게 막강한 힘이 필요함.</p></li><li><p><strong>신상필벌권의 독점:</strong> 이러한 힘은 신상필벌의 권한을 갖는 것에서 나옴. 다른 권한은 나누어주더라도 신상필벌의 권한은 절대 나누지 말아야 함.</p></li></ul><h3 id="갈등의-해결" tabindex="-1">갈등의 해결 <a class="header-anchor" href="#갈등의-해결" aria-label="Permalink to &quot;갈등의 해결&quot;">​</a></h3><ul><li><p>인간은 본래 이기적인 존재이므로 이기심 자체를 나쁘다고 볼 수 없으나, 각자가 가진 이익의 형태가 다르기 때문에 갈등이 발생함.</p></li><li><p>신하와 백성의 이익이 군주 및 국가의 이익과 일치해야 하며, 이를 해결하는 수단이 바로 &#39;법&#39;임.</p></li></ul>',28)])])}const c=i(r,[["render",n]]);export{d as __pageData,c as default};
